        .with_workspace(".")?
        .with_file("pyproject.toml", CUSTOM_EXTENSION_CONFIG)?
        .build();

    server.open_text_document("test.thing", CUSTOM_EXTENSION_MARKDOWN, 1);

    let edits = server.format_request("test.thing");

    assert_json_snapshot!(
